  1809                  break;
  1810
  1811          case DLT_LINUX_SLL:
  1812                  swap_linux_sll_header(hdr, data);
  1813                  break;
  1814
  1815          case DLT_LINUX_SLL2:
  1816                  swap_linux_sll2_header(hdr, data);
  1817                  break;
  1818
  1819          case DLT_USB_LINUX:
