    30  /*
    31   * Compute, from the data provided by the Linux USB memory-mapped capture
    32   * mechanism, the amount of packet data that would have been provided
    33   * had the capture mechanism not chopped off any data at the end, if, in
    34   * fact, it did so.
    35   *
    36   * Set the "unsliced length" field of the packet header to that value.
    37   */
    38  void
    39  fix_linux_usb_mmapped_length(struct pcap_pkthdr *pkth, const u_char *bp)
    40  {
    41          const pcap_usb_header_mmapped *hdr;
    42          u_int bytes_left;
    43
    44          bytes_left = pkth->caplen;
    45          if (bytes_left < sizeof (pcap_usb_header_mmapped)) {
    46                  /*
    47                   * We don't have the full metadata header, so give up.
    48                   */
    49                  return;
    50          }
    51          bytes_left -= sizeof (pcap_usb_header_mmapped);
    52
    53          hdr = (const pcap_usb_header_mmapped *) bp;
    54          if (!hdr->data_flag && hdr->transfer_type == URB_ISOCHRONOUS &&
    55              hdr->event_type == URB_COMPLETE &&
    56              (hdr->endpoint_number & URB_TRANSFER_IN) &&
    57              pkth->len == sizeof(pcap_usb_header_mmapped) +
    58                           (hdr->ndesc * sizeof (usb_isodesc)) + hdr->urb_len) {
    59                  usb_isodesc *descs;
    60                  u_int pre_truncation_data_len, pre_truncation_len;
    61
    62                  descs = (usb_isodesc *) (bp + sizeof(pcap_usb_header_mmapped));
    63
    64                  /*
    65                   * We have data (yes, data_flag is 0 if we *do* have data),
    66                   * and this is a "this is complete" incoming isochronous
    67                   * transfer event, and the length was calculated based
    68                   * on the URB length.
    69                   *
    70                   * That's not correct, because the data isn't contiguous,
    71                   * and the isochronous descriptos show how it's scattered.
    72                   *
    73                   * Find the end of the last chunk of data in the buffer
    74                   * referred to by the isochronous descriptors; that indicates
    75                   * how far into the buffer the data would have gone.
    76                   *
    77                   * Make sure we don't run past the end of the captured data
    78                   * while processing the isochronous descriptors.
    79                   */
    80                  pre_truncation_data_len = 0;
    81                  for (uint32_t desc = 0;
    82                      desc < hdr->ndesc && bytes_left >= sizeof (usb_isodesc);
    83                      desc++, bytes_left -= sizeof (usb_isodesc)) {
    84                          u_int desc_end;
    85
    86                          desc_end = descs[desc].offset + descs[desc].len;
    87                          if (desc_end > pre_truncation_data_len)
    88                                  pre_truncation_data_len = desc_end;
    89                  }
    90
    91                  /*
    92                   * Now calculate the total length based on that data
    93                   * length.
    94                   */
    95                  pre_truncation_len = sizeof(pcap_usb_header_mmapped) +
    96                      (hdr->ndesc * sizeof (usb_isodesc)) +
    97                      pre_truncation_data_len;
    98
    99                  /*
   100                   * If that's greater than or equal to the captured length,
   101                   * use that as the length.
   102                   */
   103                  if (pre_truncation_len >= pkth->caplen)
   104                          pkth->len = pre_truncation_len;
   105
   106                  /*
   107                   * If the captured length is greater than the length,
   108                   * use the captured length.
   109                   *
   110                   * For completion events for incoming isochronous transfers,
   111                   * it's based on data_len, which is calculated the same way
   112                   * we calculated pre_truncation_data_len above, except that
   113                   * it has access to all the isochronous descriptors, not
   114                   * just the ones that the kernel were able to provide us or,
   115                   * for a capture file, that weren't sliced off by a snapshot
   116                   * length.
   117                   *
   118                   * However, it might have been reduced by the USB capture
   119                   * mechanism arbitrarily limiting the amount of data it
   120                   * provides to userland, or by the libpcap capture code
   650                                  }
   651                                  return (-1);
   652                          }
   653                          bytes_to_discard -= amt_read;
   654                  }
   655
   656                  /*
   657                   * Adjust caplen accordingly, so we don't get confused later
   658                   * as to how many bytes we have to play with.
   659                   */
   660                  hdr->caplen = p->snapshot;
   661          } else {
   662                  /*
   663                   * The packet is within the snapshot length for this file.
   664                   */
   665                  if (hdr->caplen > p->bufsize) {
   666                          /*
   667                           * Grow the buffer to the next power of 2, or
   668                           * the snaplen, whichever is lower.
   669                           */
   670                          u_int new_bufsize;
   671
   672                          new_bufsize = hdr->caplen;
   673                          /*
   674                           * https://graphics.stanford.edu/~seander/bithacks.html#RoundUpPowerOf2
   675                           */
   676                          new_bufsize--;
   677                          new_bufsize |= new_bufsize >> 1;
   678                          new_bufsize |= new_bufsize >> 2;
   679                          new_bufsize |= new_bufsize >> 4;
   680                          new_bufsize |= new_bufsize >> 8;
   681                          new_bufsize |= new_bufsize >> 16;
   682                          new_bufsize++;
   683
   684                          if (new_bufsize > (u_int)p->snapshot)
   685                                  new_bufsize = p->snapshot;
   686
   687                          if (!grow_buffer(p, new_bufsize))
   688                                  return (-1);
   689                  }
   690
   691                  /* read the packet itself */
   692                  amt_read = fread(p->buffer, 1, hdr->caplen, fp);
   693                  if (amt_read != hdr->caplen) {
   694                          if (ferror(fp)) {
   695                                  pcap_fmt_errmsg_for_errno(p->errbuf,
   696                                      PCAP_ERRBUF_SIZE, errno,
   697                                      "error reading dump file");
   698                          } else {
   699                                  snprintf(p->errbuf, PCAP_ERRBUF_SIZE,
   700                                      "truncated dump file; tried to read %u captured bytes, only got %zu",
   701                                      hdr->caplen, amt_read);
   702                          }
   703                          return (-1);
   704                  }
   705          }
   706          *data = p->buffer;
   707
   708          if (p->swapped)
   709                  swap_pseudo_headers(p->linktype, hdr, *data);
   710
   711          fixup_pcap_pkthdr(p->linktype, hdr, *data);
   712
   713          return (1);
   714  }
